        return [(G@np.array([[1.,t],[t,1.]])@G.T,.5),(G@np.array([[1.,-t],[-t,1.]])@G.T,.5)]
    return [(A,w/4) for A,w in branch(P,Q,depth-1)]+[(L,.25)]+[(A,w/4) for A,w in branch(M,Q,depth-1)]+[(L,.25)]

